/// Parse a comma-separated value into normalized, de-duplicated, blank-free items. `lowercase` is on
/// for tags (`RF`, ` rf ` and `rf` are one) and off for refs (an id / plan ref keeps its case).
pub(crate) fn parse_csv(s: &str, lowercase: bool) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for raw in s.split(',') {
        let t = raw.trim();
        let t = if lowercase { t.to_lowercase() } else { t.to_string() };
        if !t.is_empty() && !out.contains(&t) {
            out.push(t);
        }
    }
    out
}
